    "表示": "Visible",
    "重なりあり": "Superposición detectada",
    "表示確認 JS {{arg1}} / {{arg2}} / HTML {{arg3}} / CSS {{arg4}} / 戻る {{arg5}}": "Comprobación de pantalla JS {{arg1}} / {{arg2}} / HTML {{arg3}} / CSS {{arg4}} / Volver {{arg5}}",
    "不明": "Desconocido",
