    "Ctrl・Alt・⌘との組み合わせはブラウザ操作用です。別のキーを押してください。": "Combinações com Ctrl, Alt e ⌘ são usadas pelo navegador. Pressione outra tecla.",
    "このキーはブラウザや文字入力で使います。文字・数字・矢印など、別のキーを押してください。": "Esta tecla é usada pelo navegador ou para digitar. Use outra, como letra, número ou seta.",
