    "一時停止・再開": "Pausar/retomar",
    "ランキングを読み込めませんでした。結果はそのままです。": "Não foi possível carregar o ranking. Seu resultado foi mantido.",
    "{{arg1}}位": "Posição {{arg1}}",
    "{{arg1}}点": "{{arg1}} pontos",
    "まだランキングの記録がありません。": "Ainda não há registros no ranking.",
    "新たな敵機を確認": "Novo avião inimigo detectado",
    "音 OFF": "Som DESLIGADO",
    "音 再試行": "Tentar som novamente",
    "効果音を入れる": "Ligar efeitos sonoros",
    "キーボードまたはマウスのドラッグで操縦。射撃・加速・減速はキーを長押しします。": "Pilote pelo teclado ou arrastando o mouse. Segure as teclas para disparar, acelerar e desacelerar.",
    "空のどこでもドラッグして操縦。射撃・宙返りはボタン、速度レバーは上で加速・下で減速。離すと速度を保持。": "Arraste o céu para pilotar. Use botões para disparar e fazer looping. Alavanca para cima acelera e para baixo reduz; solte para manter a velocidade.",
    "時間無制限。射撃は手動で、弾切れ後は6秒で再装填します。": "Tempo ilimitado. Disparo manual; recarga em 6 segundos após acabar a munição.",
    "キーボードまたはマウスのドラッグで操縦。射撃は自動です。弾道を見て少し先を狙ってください。": "Pilote pelo teclado ou arrastando o mouse. O disparo é automático. Observe a trajetória e mire um pouco à frente.",
    "空のどこでもドラッグして操縦。射撃は自動です。弾道を見て少し先を狙い、宙返りは画面のボタンで操作。": "Arraste o céu para pilotar. O disparo é automático. Observe a trajetória, mire à frente e use o botão para looping.",
    "名前は20文字以内で入力してください。": "Digite um nome de até 20 caracteres.",
    "前方に敵機を確認": "Avião inimigo à frente",
    "画面の更新が止まったため一時停止しました。準備ができたら再開できます。": "Pausado porque as atualizações de tela pararam. Retome quando estiver pronto.",
    "描画を復旧しています。": "Recuperando a renderização.",
