    "Ctrl・Alt・⌘との組み合わせはブラウザ操作用です。別のキーを押してください。": "Ctrl、Alt、⌘组合键用于浏览器操作。请按其他键。",
    "このキーはブラウザや文字入力で使います。文字・数字・矢印など、別のキーを押してください。": "此键用于浏览器或文字输入。请选择字母、数字、方向键等其他按键。",
