    "{{arg1}}位": "第{{arg1}}名",
    "{{arg1}}点": "{{arg1}}分",
    "まだランキングの記録がありません。": "排行榜暂无记录。",
    "新たな敵機を確認": "发现新敌机",
    "音 OFF": "声音 关",
