    "効果音を入れる": "开启音效",
    "キーボードまたはマウスのドラッグで操縦。射撃・加速・減速はキーを長押しします。": "用键盘或拖动鼠标驾驶。射击、加速、减速需长按对应按键。",
    "空のどこでもドラッグして操縦。射撃・宙返りはボタン、速度レバーは上で加速・下で減速。離すと速度を保持。": "在天空任意位置拖动来驾驶。按钮控制射击与筋斗；速度杆向上加速、向下减速，松开后维持速度。",
    "時間無制限。射撃は手動で、弾切れ後は6秒で再装填します。": "时间不限。手动射击，弹药耗尽后用6秒重新装填。",
    "キーボードまたはマウスのドラッグで操縦。射撃は自動です。弾道を見て少し先を狙ってください。": "用键盘或拖动鼠标驾驶。自动射击。观察弹道，瞄准敌机前方一点。",
    "空のどこでもドラッグして操縦。射撃は自動です。弾道を見て少し先を狙い、宙返りは画面のボタンで操作。": "在天空任意位置拖动来驾驶。自动射击。观察弹道，瞄准敌机前方一点；用画面按钮做筋斗。",
    "名前は20文字以内で入力してください。": "请输入不超过20个字符的名字。",
