    "表示確認 JS {{arg1}} / {{arg2}} / HTML {{arg3}} / CSS {{arg4}} / 戻る {{arg5}}": "표시 확인 JS {{arg1}} / {{arg2}} / HTML {{arg3}} / CSS {{arg4}} / 뒤로 {{arg5}}",
    "不明": "알 수 없음",
