    "零式艦上戦闘機 二一型": "零式艦上戰鬥機 二一型",
    "零戦二一型を基にした空戦です。ノーマルは時間無制限で手動射撃、イージーは300秒で自動射撃です。どちらも7.7mm 288発・20mm 96発を使い切ると6秒で再装填します。空のどこでもドラッグして操縦します。": "以零戰二一型為基礎的空戰。普通模式不限時、手動射擊；簡單模式300秒、自動射擊。兩者的7.7mm 288發和20mm 96發都用完後，需6秒裝填。在天空任意位置拖曳以操縱。",
    "音 ON": "聲音 開",
    "順位": "排名",
