    "飛行時間": "飛行時間",
    "飛行終了": "飛行結束",
    "高度": "高度",
    "高度1,200m以下で低高度警告が出ます。警告から10秒で飛行終了です。上昇しても警告は解除されません。一時停止中は残り時間も止まります。": "高度1,200m以下出現低空警告，警告後10秒飛行結束。上升也不會解除警告。暫停時倒數也會停止。",
