    "速度レバーの配置が重なっています。大きさや位置を調整してから保存してください。": "速度控制桿配置重疊。請調整大小或位置後儲存。",
    "設定を保存できませんでした。以前の設定で続けます。「今回だけ使う」で、ページを閉じるまで適用します。": "無法儲存設定，將沿用先前設定。選「僅本次使用」可套用至關閉頁面為止。",
