    "{{arg1}}は「{{arg2}}」で使用中です。別のキーを押してください。": "{{arg1}}已用於「{{arg2}}」。請按其他鍵。",
    "{{arg1}}を{{arg2}}に変更しました。「保存する」で適用します。": "已將{{arg1}}改為{{arg2}}。按「儲存」套用。",
    "ノーマル：時間無制限。手動射撃、弾切れで6秒再装填。速度レバーで調整します。": "普通：不限時。手動射擊，彈藥耗盡後裝填6秒。以速度控制桿調整。",
    "イージー：300秒。自動射撃、弾切れで6秒再装填。宙返りボタンだけを調整できます。": "簡單：300秒。自動射擊，彈藥耗盡後裝填6秒。只能調整筋斗按鈕。",
    "速度レバーを配置できません。大きさや位置を調整してください。": "無法放置速度控制桿。請調整大小或位置。",
    "前回の設定保存を復元する必要があります。控えの設定で表示しています。保存するで復元を再試行できます。": "需要復原上次儲存的設定。目前顯示備份設定，可按儲存重試復原。",
