    "キーボードまたはマウスのドラッグで操縦。射撃・加速・減速はキーを長押しします。": "用鍵盤或滑鼠拖曳操縱。按住按鍵射擊、加速或減速。",
    "空のどこでもドラッグして操縦。射撃・宙返りはボタン、速度レバーは上で加速・下で減速。離すと速度を保持。": "在天空任意位置拖曳以操縱。按鈕射擊、筋斗；速度控制桿向上加速、向下減速，放開保持速度。",
    "時間無制限。射撃は手動で、弾切れ後は6秒で再装填します。": "不限時。手動射擊，彈藥耗盡後需6秒裝填。",
    "キーボードまたはマウスのドラッグで操縦。射撃は自動です。弾道を見て少し先を狙ってください。": "用鍵盤或滑鼠拖曳操縱。自動射擊，觀察彈道，瞄準敵機前方一點。",
