    "Ctrl・Alt・⌘との組み合わせはブラウザ操作用です。別のキーを押してください。": "Ctrl, Alt, ⌘ birleşimleri tarayıcı içindir. Başka tuşa bas.",
    "このキーはブラウザや文字入力で使います。文字・数字・矢印など、別のキーを押してください。": "Bu tuş tarayıcı veya metin girişi içindir. Harf, sayı veya ok gibi başka tuş seç.",
