    "空のどこでもドラッグして操縦。射撃は自動です。宙返りは画面のボタンかLキーで操作。": "Kéo ở bất cứ đâu trên bầu trời để lái. Tự động bắn. Nhào vòng bằng nút màn hình hoặc phím L.",
