    "速度レバーの配置が重なっています。画面を回転するか、操作設定で位置や大きさを調整してください。": "Cần tốc độ bị chồng lấp. Xoay màn hình hoặc chỉnh vị trí, kích thước trong cài đặt điều khiển.",
    "遊び方": "Cách chơi",
    "長押し": "Nhấn giữ",
    "閉じる": "Đóng",
    "零式艦上戦闘機 二一型": "Tiêm kích hạm Zero, Kiểu Hai Mươi Mốt",
    "零戦二一型を基にした空戦です。ノーマルは時間無制限で手動射撃、イージーは300秒で自動射撃です。どちらも7.7mm 288発・20mm 96発を使い切ると6秒で再装填します。空のどこでもドラッグして操縦します。": "Không chiến dựa trên Zero Kiểu Hai Mươi Mốt. Thường không giới hạn thời gian, bắn thủ công; Dễ có 300 giây, tự động bắn. Cả hai nạp lại trong 6 giây khi dùng hết 288 viên 7.7mm và 96 viên 20mm. Kéo trên bầu trời để lái.",
    "音 ON": "Âm thanh BẬT",
    "順位": "Hạng",
    "飛行を再開": "Tiếp tục bay",
    "飛行時間": "Thời gian bay",
    "飛行終了": "Chuyến bay kết thúc",
    "高度": "Độ cao",
    "高度1,200m以下で低高度警告が出ます。警告から10秒で飛行終了です。上昇しても警告は解除されません。一時停止中は残り時間も止まります。": "Ở độ cao 1,200m trở xuống có cảnh báo thấp. Chuyến bay kết thúc sau 10 giây. Bay lên không gỡ cảnh báo. Khi tạm dừng, đếm ngược cũng dừng.",
