    "Escは入力の取り消し、Tabは画面の移動に使います。Ctrl・Alt・⌘の組み合わせやブラウザ専用キーは登録できません。": "Esc hủy nhập, Tab chuyển tiêu điểm. Không gán được tổ hợp Ctrl, Alt, ⌘ hoặc phím dành riêng cho trình duyệt.",
    "FLIGHT CONTROLS": "ĐIỀU KHIỂN BAY",
    "このブラウザでは設定を保存できないため、今回の表示中だけ有効です。": "Trình duyệt không lưu được cài đặt, chỉ có hiệu lực khi trang còn mở.",
