    "変更したい操作を選んで、使うキーを1つ押してください。左右のShift・テンキーも区別します。両モード共通です。": "Chọn thao tác rồi nhấn 1 phím muốn dùng. Phân biệt Shift trái/phải và bàn phím số. Dùng chung cho cả hai chế độ.",
