    "ノーマルのみ": "Chỉ Thường",
    "{{arg1}}に使うキーを押してください。Escで取り消します。": "Nhấn phím cho {{arg1}}. Esc để hủy.",
    "標準のキーに戻しました。「保存する」で適用します。": "Đã khôi phục phím mặc định. Nhấn Lưu để áp dụng.",
    "速度レバーの配置が重なっています。大きさや位置を調整してから保存してください。": "Cần tốc độ bị chồng lấp. Chỉnh kích thước hoặc vị trí trước khi lưu.",
    "設定を保存できませんでした。以前の設定で続けます。「今回だけ使う」で、ページを閉じるまで適用します。": "Không lưu được cài đặt, sẽ dùng cài đặt cũ. Chỉ dùng lần này áp dụng đến khi đóng trang.",
    "今回だけ使う": "Chỉ dùng lần này",
