    "キーの変更を取り消しました。": "Đã hủy đổi phím.",
    "{{arg1}}は「{{arg2}}」で使用中です。別のキーを押してください。": "{{arg1}} đã dùng cho {{arg2}}. Nhấn phím khác.",
    "{{arg1}}を{{arg2}}に変更しました。「保存する」で適用します。": "Đã đổi {{arg1}} thành {{arg2}}. Nhấn Lưu để áp dụng.",
    "ノーマル：時間無制限。手動射撃、弾切れで6秒再装填。速度レバーで調整します。": "Thường: không giới hạn thời gian. Bắn thủ công, nạp 6 giây khi hết đạn. Chỉnh tốc độ bằng cần.",
    "イージー：300秒。自動射撃、弾切れで6秒再装填。宙返りボタンだけを調整できます。": "Dễ: 300 giây. Tự động bắn, nạp 6 giây khi hết đạn. Chỉ chỉnh được nút nhào vòng.",
    "速度レバーを配置できません。大きさや位置を調整してください。": "Không đặt được cần tốc độ. Chỉnh kích thước hoặc vị trí.",
    "前回の設定保存を復元する必要があります。控えの設定で表示しています。保存するで復元を再試行できます。": "Cần khôi phục lần lưu cài đặt trước. Đang hiển thị bản dự phòng. Nhấn Lưu để thử khôi phục lại.",
    "このブラウザでは保存できません。今回だけ使う設定は、ページを閉じるまで有効です。": "Trình duyệt này không lưu được. Cài đặt tạm thời có hiệu lực đến khi đóng trang.",
