    "Ctrl・Alt・⌘との組み合わせはブラウザ操作用です。別のキーを押してください。": "Tổ hợp Ctrl, Alt, ⌘ dành cho trình duyệt. Hãy nhấn phím khác.",
    "このキーはブラウザや文字入力で使います。文字・数字・矢印など、別のキーを押してください。": "Phím này dành cho trình duyệt hoặc nhập văn bản. Chọn chữ, số, mũi tên hay phím khác.",
