    "キーボードまたはマウスのドラッグで操縦。射撃・加速・減速はキーを長押しします。": "Lái bằng bàn phím hoặc kéo chuột. Giữ phím để bắn, tăng tốc, giảm tốc.",
    "空のどこでもドラッグして操縦。射撃・宙返りはボタン、速度レバーは上で加速・下で減速。離すと速度を保持。": "Kéo trên bầu trời để lái. Nút để bắn và nhào vòng; cần lên tăng tốc, xuống giảm tốc. Thả để giữ tốc độ.",
    "時間無制限。射撃は手動で、弾切れ後は6秒で再装填します。": "Không giới hạn thời gian. Bắn thủ công, nạp lại 6 giây sau khi hết đạn.",
    "キーボードまたはマウスのドラッグで操縦。射撃は自動です。弾道を見て少し先を狙ってください。": "Lái bằng bàn phím hoặc kéo chuột. Tự động bắn. Quan sát đường đạn và ngắm trước địch một chút.",
    "空のどこでもドラッグして操縦。射撃は自動です。弾道を見て少し先を狙い、宙返りは画面のボタンで操作。": "Kéo trên bầu trời để lái. Tự động bắn. Quan sát đường đạn, ngắm trước địch một chút, dùng nút màn hình để nhào vòng.",
    "名前は20文字以内で入力してください。": "Nhập tên tối đa 20 ký tự.",
    "前方に敵機を確認": "Phát hiện địch phía trước",
    "画面の更新が止まったため一時停止しました。準備ができたら再開できます。": "Tạm dừng vì màn hình ngừng cập nhật. Có thể tiếp tục khi sẵn sàng.",
