    "零戦二一型を基にした空戦です。ノーマルは時間無制限で手動射撃、イージーは300秒で自動射撃です。どちらも7.7mm 288発・20mm 96発を使い切ると6秒で再装填します。空のどこでもドラッグして操縦します。": "การรบที่อิงซีโร่แบบยี่สิบเอ็ด ปกติไม่จำกัดเวลาและยิงเอง ง่ายมี 300 วินาทีและยิงอัตโนมัติ ทั้งคู่เติมใน 6 วินาทีเมื่อใช้กระสุน 7.7mm 288 นัดและ 20mm 96 นัดหมด ลากบนฟ้าเพื่อบังคับ",
