    "ノーマル：時間無制限。手動射撃、弾切れで6秒再装填。速度レバーで調整します。": "ปกติ: ไม่จำกัดเวลา ยิงเอง เติม 6 วินาทีเมื่อหมด ใช้คันโยกปรับความเร็ว",
    "イージー：300秒。自動射撃、弾切れで6秒再装填。宙返りボタンだけを調整できます。": "ง่าย: 300 วินาที ยิงอัตโนมัติ เติม 6 วินาทีเมื่อหมด ปรับได้เฉพาะปุ่มตีลังกา",
    "速度レバーを配置できません。大きさや位置を調整してください。": "วางคันโยกความเร็วไม่ได้ โปรดปรับขนาดหรือตำแหน่ง",
