    "飛行時間：{{arg1}}": "เวลาบิน: {{arg1}}",
    "読み取れないプレイ記録があります。元の記録は保持し、ほかの記録の処理を続けます。": "มีบันทึกการเล่นที่อ่านไม่ได้ ระบบจะเก็บบันทึกต้นฉบับไว้และประมวลผลบันทึกอื่นต่อไป"
